  "shell.edges.round": "Gerundet",
  "shell.edges.sharp": "Scharfkantig",
  "shell.edgesHint": "Gilt dort, wo Innenwände auseinanderlaufen, an einer Stufe oder Öffnung. Die Ecken eines einfachen Quaders bleiben innen scharf - runde zuerst seine Außenkanten, dann wird auch das Innere rund.",
  "shell.apply": "Aushöhlen",
  "shell.working": "Wird ausgehöhlt…",
  "shell.cancel": "Aushöhlen abbrechen",
  "shell.errorTooThick": "Die Wände können für diesen Körper nicht so dick sein. Bitte eine dünnere Wandstärke wählen.",
  "shell.errorRoundedEdges": "Diese Box hat gerundete Ober- und Unterkanten, und die Wand muss deutlich dünner sein als diese Rundung. Wähle eine dünnere Wand oder setze die Rundung der Ober- und Unterkanten auf 0, bevor du aushöhlst. Klappt es trotzdem nicht, speichert „Fehlerbericht“ in der Fußzeile den Entwurf für eine Meldung.",
  "shell.errorCannotHollow": "Dieser Körper lässt sich nicht aushöhlen, auch nicht mit einer sehr dünnen Wand. Sein Umriss ist wahrscheinlich nicht sauber genug für den CAD-Kern; eine Aussparung, die den Außenrand berührt, etwa eine bis zur Unterkante reichende Tür bei einer importierten Form, kann das auslösen.",
  "shell.errorNoFlatTop": "Dieser Körper hat oben keine ebene Fläche, die geöffnet werden kann. Kugeln und freie Formen können so nicht ausgehöhlt werden.",
  "shell.errorNoFlatBottom": "Dieser Körper hat unten keine ebene Fläche, die geöffnet werden kann.",
  "edge.errorOldRevolve": "Dieser gedrehte Körper wurde von einer älteren layerling-Fassung als Netz gebaut. Öffne „Skizze bearbeiten“ und schließe ihn neu ab, dann ist er ein exakter Körper und lässt sich aushöhlen, verrunden und fasen.",
  "shell.errorNoFlatSide": "Dieser Körper hat auf der gewählten Seite keine ebene Fläche, die geöffnet werden kann.",
  "shell.errorProjectChanged": "Das Objekt oder Projekt wurde während des Aushöhlens geändert. Bitte erneut versuchen.",
  "shell.errorFailed": "Der Körper konnte nicht ausgehöhlt werden. Bitte eine andere Wandstärke oder Öffnung wählen.",
  "status.shelled": "Mit {size} mm Wandstärke ausgehöhlt",
  "status.shelledSealed": "Hollowed with {size} mm walls, sealed all round - the cavity is inside, so it looks solid. Open a side to see it.",
  "status.shelledMcp": "MCP hat das Objekt mit {size} mm Wandstärke ausgehöhlt",
  "status.shellRebuilt": "Wände neu berechnet, wieder {size} mm dick",
  "status.shellRebuildFailed": "In dieser Größe ließ sich die Aushöhlung nicht neu berechnen. Die Wände sind mitskaliert.",
  "status.sketchRebuildFailed": "Der Skizzenkörper ließ sich in dieser Größe nicht neu aufbauen. Fase und Rundung gehen an ihm erst wieder, wenn du die Skizze bearbeitest.",
  "edge.revertShell": "Aushöhlung ({size} mm Wand)",
