  "draft.subtitle": "Lean side walls in towards the top",
  "draft.help": "Click the side walls to lean (click again to unpick). They lean in from the bottom of the part as they go up - a negative angle leans them out.",
  "draft.angle": "Angle",
  "draft.hint": "1-3° lets a part come out of a mould or a printed press; larger angles give a tapered look.",
  "draft.apply": "Apply draft",
  "draft.working": "Leaning…",
  "draft.done": "Drafted {count} face(s) by {angle}°.",
  "deleteFace.subtitle": "Die Flächen ringsum schließen die Lücke",
  "deleteFace.help": "Klicke die Flächen an, die weg sollen; ein zweiter Klick nimmt eine Fläche wieder heraus. Die Flächen ringsum wachsen, bis die Lücke geschlossen ist: Eine Verrundung, ein Loch oder ein Zapfen ist weg, und der Körper bleibt exakt.",
  "deleteFace.preparing": "Flächen werden gelesen…",
  "deleteFace.countNone": "Noch keine Fläche gewählt",
  "deleteFace.countOne": "1 Fläche gewählt",
  "deleteFace.countMany": "{count} Flächen gewählt",
  "deleteFace.apply": "Löschen",
  "deleteFace.working": "Flächen werden gelöscht…",
  "deleteFace.cancel": "Fläche löschen abbrechen",
  "deleteFace.errorUnchanged": "Diese Flächen lassen sich nicht löschen: Die Flächen ringsum schließen die Lücke nicht. Alle Flächen des Teils wählen, das weg soll - etwa alle Flächen einer Verrundung oder die ganze Wand eines Lochs - und keine Fläche des Körpers selbst.",
  "deleteFace.errorMesh": "Dieser Körper hat keine exakten Flächen zum Löschen: Pare 3D führt ihn als Netz, wie eine importierte STL-, OBJ- oder 3MF-Datei, einen geteilten, um einen Zylinder gewickelten oder vereinfachten Körper oder eine sehr detailreiche Form, etwa einen langen Text. Ein als STEP importiertes Teil hat exakte Flächen.",
  "deleteFace.errorResized": "Dieser Körper wurde mit „Kantengröße beim Skalieren beibehalten“ in der Größe geändert, deshalb passen seine exakten Flächen nicht mehr zu seiner Größe. Die Größenänderung rückgängig machen, die Flächen löschen und danach die Größe wieder ändern.",
  "deleteFace.errorProjectChanged": "Das Objekt oder Projekt wurde während des Löschens geändert. Bitte erneut versuchen.",
  "deleteFace.errorFailed": "Die Flächen konnten nicht gelöscht werden. Bitte andere Flächen wählen.",
  "deleteFace.errorNoFaces": "Die Flächen dieses Körpers konnten nicht gelesen werden. Das Werkzeug schließen und neu öffnen.",
  "deleteFace.errorTooSlow": "Das Löschen dieser Flächen hat zu lange gedauert und wurde nach 45 Sekunden abgebrochen; nichts hat sich geändert. Der CAD-Rechenkern kommt mit diesen Flächen an diesem Teil nicht zurecht: Bitte andere oder weniger Flächen wählen.",
  "status.facesDeletedOne": "1 Fläche gelöscht",
  "status.facesDeletedMany": "{count} Flächen gelöscht",
  "status.facesDeletedMcpOne": "1 Fläche von MCP gelöscht",
  "status.facesDeletedMcpMany": "{count} Flächen von MCP gelöscht",
  "status.deleteFaceCancelled": "Fläche löschen abgebrochen",
  "status.deleteFaceCancelledChanged": "Fläche löschen abgebrochen, weil sich das Objekt geändert hat",
  "edge.revertDeleteFaceOne": "Gelöschte Flächen (1 Fläche)",
