  "readyParts.clickerGapOption": "{gap} mm Abstand",
  "readyParts.clickerGapHint": "Wie weit der Schalter aus dem Unterteil ragt, also der Abstand zwischen den Hälften. 2,5 mm reichen, damit ein klickender (blauer) Schalter klickt (bei etwa 2,2 mm); mehr gibt einen längeren Druck.",
  "readyParts.clickerGap": "Abstand zwischen den Hälften",
  "clicker.notFlat": "Diese Fläche ist nicht flach; der Schneider wurde an der Klickstelle abgesetzt und nicht eingeschnitten. Klicke eine flache Fläche oder gruppiere selbst.",
