  "clicker.cut": "{cutter} in {part} eingeschnitten, mittig auf der Fläche.",
  "readyParts.clickerHowTo": "Mach aus jeder Form einen Klicker mit einem Tastaturschalter (Cherry-MX-Art). Teile die Form in Unterteil und Oberteil und lege jede Hälfte mit der flachen Seite nach oben. Wähle den Abstand, füge das Klicker-Unterteil hinzu und klicke auf die flache Seite des Unterteils; dann das Klicker-Oberteil und die flache Seite des Oberteils. Jeder Schneider kommt in die Mitte der Fläche und wird sofort eingeschnitten. Sie behalten ihre Größe und passen so zu Standardschaltern.",
  "readyParts.clickerBase": "Klicker-Unterteil",
  "readyParts.clickerBaseHint": "Die Tasche, in die der Schalter gedrückt wird, so tief, dass nur {gap} mm herausstehen - der Abstand zwischen den Hälften. Kerben halten seine Klammern.",
  "readyParts.clickerTop": "Klicker-Oberteil",
