  "export.obj.description": "Universelles 3D-Netz",
  "export.obj.note": "Ein breit unterstütztes Netzformat für Modellierung, Bildberechnung und Austausch. Die Farben stehen an den Eckpunkten, Bambu Studio und OrcaSlicer lesen sie.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "Behält Quader, Zylinder, Kugeln und Kegel als exakte CAD-Geometrie, dazu alles mit verrundeten oder gefasten Kanten und Körper, die als STEP hereingekommen sind. Gewinde, Federn und Zahnräder gehen ebenfalls als exakter Körper. Verjüngte, geneigte und verdrehte Formen gehen exakt mit. Eingelesene Netze zum Beispiel kann STEP nicht tragen — die gehen als STL.",
